import pandas as pd

def shortest_distance(point: pd.DataFrame) -> pd.DataFrame:
    sorted_pts = point['x'].sort_values()
    diffs = sorted_pts.diff().dropna()
    min_diff = diffs.min() if not diffs.empty else None
    return pd.DataFrame({'shortest': [min_diff]})
